import { allocateOrder, restock } from "../domain/warehouse.mjs";

export class WarehouseService {
  constructor(repository) {
    this.repository = repository;
  }

  allocateOrder(input) {
    const state = this.repository.load();
    const result = allocateOrder(state, input);
    if (result.ok) this.repository.save(state);
    return result;
  }

  restock(input) {
    const state = this.repository.load();
    const quantity = restock(state, input);
    this.repository.save(state);
    return quantity;
  }

  snapshot() {
    return this.repository.load();
  }
}

