+import test from "node:test";
+import assert from "node:assert/strict";
+import {
+  allocateOrder,
+  confirmReservation,
+  createWarehouseState,
+  listReservations,
+  releaseExpired,
+  reserveStock
+} from "../src/domain/warehouse.mjs";
+import { InMemoryWarehouseRepository } from "../src/infrastructure/in-memory-repository.mjs";
+
+function reservationOverview(snapshot) {
+  const activeReservations = snapshot.reservations.filter((reservation) => reservation.status === "active");
+  const expiredReservations = snapshot.reservations.filter((reservation) => reservation.status === "expired");
+  return {
+    activeCount: activeReservations.length,
+    expiredCount: expiredReservations.length,
+    reservedUnits: activeReservations.reduce((total, reservation) => {
+      return total + reservation.lines.reduce((lineTotal, line) => lineTotal + line.quantity, 0);
+    }, 0),
+    nextExpiry:
+      activeReservations.length === 0
+        ? null
+        : activeReservations
+            .map((reservation) => reservation.expiresAt)
+            .reduce((earliest, expiresAt) => (expiresAt < earliest ? expiresAt : earliest))
+  };
+}
+
+test("reserves stock, records the creation event, and persists reservation state", () => {
+  const repository = new InMemoryWarehouseRepository(createWarehouseState({ A: 10 }));
+  const state = repository.load();
+  const now = new Date("2026-08-09T12:00:00Z");
+
+  const result = reserveStock(state, {
+    reservationId: "R-1",
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 3 }],
+    ttlMinutes: 30,
+    now
+  });
+
+  assert.equal(result.ok, true);
+  assert.equal(state.stockBySku.A, 7);
+  assert.equal(state.reservations.length, 1);
+  assert.equal(state.reservations[0].status, "active");
+  assert.deepEqual(state.reservations[0].expiresAt, new Date("2026-08-09T12:30:00Z"));
+  assert.equal(state.events.at(-1).type, "reservation-created");
+  assert.deepEqual(reservationOverview(state), {
+    activeCount: 1,
+    expiredCount: 0,
+    reservedUnits: 3,
+    nextExpiry: new Date("2026-08-09T12:30:00Z")
+  });
+
+  repository.save(state);
+  const loaded = repository.load();
+  loaded.reservations[0].status = "tampered";
+  assert.equal(repository.load().reservations[0].status, "active");
+});
+
+test("validates reservation identifiers, ttl, quantities, and duplicate line skuIds", () => {
+  const state = createWarehouseState({ A: 5 });
+
+  assert.throws(
+    () =>
+      reserveStock(state, {
+        reservationId: "",
+        orderId: "O-1",
+        lines: [{ skuId: "A", quantity: 1 }],
+        ttlMinutes: 15,
+        now: new Date("2026-08-09T12:00:00Z")
+      }),
+    /reservationId is required/
+  );
+
+  assert.throws(
+    () =>
+      reserveStock(state, {
+        reservationId: "R-1",
+        orderId: "",
+        lines: [{ skuId: "A", quantity: 1 }],
+        ttlMinutes: 15,
+        now: new Date("2026-08-09T12:00:00Z")
+      }),
+    /orderId is required/
+  );
+
+  assert.throws(
+    () =>
+      reserveStock(state, {
+        reservationId: "R-1",
+        orderId: "O-1",
+        lines: [{ skuId: "A", quantity: 1 }],
+        ttlMinutes: 0,
+        now: new Date("2026-08-09T12:00:00Z")
+      }),
+    /ttlMinutes must be a positive integer/
+  );
+
+  assert.throws(
+    () =>
+      reserveStock(state, {
+        reservationId: "R-1",
+        orderId: "O-1",
+        lines: [{ skuId: "A", quantity: 0 }],
+        ttlMinutes: 15,
+        now: new Date("2026-08-09T12:00:00Z")
+      }),
+    /quantity must be a positive integer/
+  );
+
+  assert.throws(
+    () =>
+      reserveStock(state, {
+        reservationId: "R-1",
+        orderId: "O-1",
+        lines: [
+          { skuId: "A", quantity: 1 },
+          { skuId: "A", quantity: 1 }
+        ],
+        ttlMinutes: 15,
+        now: new Date("2026-08-09T12:00:00Z")
+      }),
+    /duplicate skuId/
+  );
+});
+
+test("confirms an active reservation without decrementing stock again", () => {
+  const state = createWarehouseState({ A: 6 });
+  reserveStock(state, {
+    reservationId: "R-1",
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 2 }],
+    ttlMinutes: 20,
+    now: new Date("2026-08-09T12:00:00Z")
+  });
+
+  const result = confirmReservation(state, { reservationId: "R-1" });
+
+  assert.equal(result.ok, true);
+  assert.equal(state.stockBySku.A, 4);
+  assert.equal(state.orders.length, 1);
+  assert.equal(state.orders[0].status, "confirmed");
+  assert.equal(state.orders[0].reservationId, "R-1");
+  assert.equal(state.reservations[0].status, "confirmed");
+  assert.deepEqual(state.events.map((event) => event.type), ["reservation-created", "reservation-confirmed"]);
+  assert.deepEqual(listReservations(state).map((reservation) => reservation.status), ["confirmed"]);
+});
+
+test("releases expired reservations once and leaves confirmed reservations alone", () => {
+  const state = createWarehouseState({ A: 8, B: 4 });
+  reserveStock(state, {
+    reservationId: "R-1",
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 3 }],
+    ttlMinutes: 15,
+    now: new Date("2026-08-09T12:00:00Z")
+  });
+  reserveStock(state, {
+    reservationId: "R-2",
+    orderId: "O-2",
+    lines: [{ skuId: "B", quantity: 2 }],
+    ttlMinutes: 60,
+    now: new Date("2026-08-09T12:00:00Z")
+  });
+  confirmReservation(state, { reservationId: "R-2" });
+
+  const firstRelease = releaseExpired(state, { now: new Date("2026-08-09T12:20:00Z") });
+
+  assert.equal(firstRelease.ok, true);
+  assert.equal(firstRelease.reservations.length, 1);
+  assert.equal(state.stockBySku.A, 8);
+  assert.equal(state.stockBySku.B, 2);
+  assert.equal(state.reservations.find((reservation) => reservation.reservationId === "R-1").status, "expired");
+  assert.equal(state.reservations.find((reservation) => reservation.reservationId === "R-2").status, "confirmed");
+  assert.equal(state.events.at(-1).type, "reservation-expired");
+  assert.deepEqual(reservationOverview(state), {
+    activeCount: 0,
+    expiredCount: 1,
+    reservedUnits: 0,
+    nextExpiry: null
+  });
+
+  const eventCount = state.events.length;
+  const secondRelease = releaseExpired(state, { now: new Date("2026-08-09T13:00:00Z") });
+
+  assert.equal(secondRelease.ok, true);
+  assert.equal(secondRelease.reservations.length, 0);
+  assert.equal(state.events.length, eventCount);
+  assert.equal(state.stockBySku.A, 8);
+  assert.equal(state.stockBySku.B, 2);
+});
+
+test("allocation still works with reservation state present", () => {
+  const state = createWarehouseState({ A: 5 });
+  state.reservations.push({
+    reservationId: "R-1",
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 1 }],
+    ttlMinutes: 10,
+    status: "active",
+    createdAt: new Date("2026-08-09T12:00:00Z"),
+    expiresAt: new Date("2026-08-09T12:10:00Z")
+  });
+
+  const result = allocateOrder(state, {
+    orderId: "O-2",
+    lines: [{ skuId: "A", quantity: 2 }]
+  });
+
+  assert.equal(result.ok, true);
+  assert.equal(state.stockBySku.A, 3);
+  assert.equal(state.orders[0].status, "allocated");
+  assert.equal(state.events.at(-1).type, "order-allocated");
+});

