+import test from "node:test";
+import assert from "node:assert/strict";
+import {
+  allocateOrder,
+  confirmReservation,
+  createWarehouseState,
+  listReservations,
+  releaseExpired,
+  reserveStock
+} from "../src/domain/warehouse.mjs";
+import { InMemoryWarehouseRepository } from "../src/infrastructure/in-memory-repository.mjs";
+
+function reservationOverview(snapshot) {
+  const activeReservations = snapshot.reservations.filter((reservation) => reservation.status === "active");
+  const expiredReservations = snapshot.reservations.filter((reservation) => reservation.status === "expired");
+  return {
+    activeCount: activeReservations.length,
+    expiredCount: expiredReservations.length,
+    reservedUnits: activeReservations.reduce((total, reservation) => {
+      return total + reservation.lines.reduce((lineTotal, line) => lineTotal + line.quantity, 0);
+    }, 0),
+    nextExpiry:
+      activeReservations.length === 0
+        ? null
+        : activeReservations
+            .map((reservation) => reservation.expiresAt)
+            .reduce((earliest, expiresAt) => (expiresAt < earliest ? expiresAt : earliest))
+  };
+}
+
+test("reserves stock, records the creation event, and persists reservation state", () => {
+  const repository = new InMemoryWarehouseRepository(createWarehouseState({ A: 10 }));
+  const state = repository.load();
+  const now = new Date("2026-08-09T12:00:00Z");
+
+  const result = reserveStock(state, {
+    reservationId: "R-1",
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 3 }],
+    ttlMinutes: 30,
+    now
+  });
+
+  assert.equal(result.ok, true);
+  assert.equal(state.stockBySku.A, 7);
+  assert.equal(state.reservations.length, 1);
+  assert.equal(state.reservations[0].status, "active");
+  assert.deepEqual(state.reservations[0].expiresAt, new Date("2026-08-09T12:30:00Z"));
+  assert.equal(state.events.at(-1).type, "reservation-created");
+  assert.deepEqual(reservationOverview(state), {
+    activeCount: 1,
+    expiredCount: 0,
+    reservedUnits: 3,
+    nextExpiry: new Date("2026-08-09T12:30:00Z")
+  });
+
+  repository.save(state);
+  const loaded = repository.load();
+  loaded.reservations[0].status = "tampered";
+  assert.equal(repository.load().reservations[0].status, "active");
+});
+
+test("validates reservation identifiers, ttl, quantities, and duplicate line skuIds", () => {
+  const state = createWarehouseState({ A: 5 });
+
+  assert.throws(
+    () =>
+      reserveStock(state, {
+        reservationId: "",
+        orderId: "O-1",
+        lines: [{ skuId: "A", quantity: 1 }],
+        ttlMinutes: 15,
+        now: new Date("2026-08-09T12:00:00Z")
+      }),
+    /reservationId is required/
+  );
+
+  assert.throws(
+    () =>
+      reserveStock(state, {
+        reservationId: "R-1",
+        orderId: "",
+        lines: [{ skuId: "A", quantity: 1 }],
+        ttlMinutes: 15,
+        now: new Date("2026-08-09T12:00:00Z")
+      }),
+    /orderId is required/
+  );
+
+  assert.throws(
+    () =>
+      reserveStock(state, {
+        reservationId: "R-1",
+        orderId: "O-1",
+        lines: [{ skuId: "A", quantity: 1 }],
+        ttlMinutes: 0,
+        now: new Date("2026-08-09T12:00:00Z")
+      }),
+    /ttlMinutes must be a positive integer/
+  );
+
+  assert.throws(
+    () =>
+      reserveStock(state, {
+        reservationId: "R-1",
+        orderId: "O-1",
+        lines: [{ skuId: "A", quantity: 0 }],
+        ttlMinutes: 15,
+        now: new Date("2026-08-09T12:00:00Z")
+      }),
+    /quantity must be a positive integer/
