+        ],
+        ttlMinutes: 15,
+        now: new Date("2026-08-09T12:00:00Z")
+      }),
+    /duplicate skuId/
+  );
+});
+
+test("confirms an active reservation without decrementing stock again", () => {
+  const state = createWarehouseState({ A: 6 });
+  reserveStock(state, {
+    reservationId: "R-1",
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 2 }],
+    ttlMinutes: 20,
+    now: new Date("2026-08-09T12:00:00Z")
+  });
+
+  const result = confirmReservation(state, { reservationId: "R-1" });
+
+  assert.equal(result.ok, true);
+  assert.equal(state.stockBySku.A, 4);
+  assert.equal(state.orders.length, 1);
+  assert.equal(state.orders[0].status, "confirmed");
+  assert.equal(state.orders[0].reservationId, "R-1");
+  assert.equal(state.reservations[0].status, "confirmed");
+  assert.deepEqual(state.events.map((event) => event.type), ["reservation-created", "reservation-confirmed"]);
+  assert.deepEqual(listReservations(state).map((reservation) => reservation.status), ["confirmed"]);
+});
+
+test("releases expired reservations once and leaves confirmed reservations alone", () => {
+  const state = createWarehouseState({ A: 8, B: 4 });
+  reserveStock(state, {
+    reservationId: "R-1",
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 3 }],
+    ttlMinutes: 15,
+    now: new Date("2026-08-09T12:00:00Z")
+  });
+  reserveStock(state, {
+    reservationId: "R-2",
+    orderId: "O-2",
+    lines: [{ skuId: "B", quantity: 2 }],
+    ttlMinutes: 60,
+    now: new Date("2026-08-09T12:00:00Z")
+  });
+  confirmReservation(state, { reservationId: "R-2" });
+
+  const firstRelease = releaseExpired(state, { now: new Date("2026-08-09T12:20:00Z") });
+
+  assert.equal(firstRelease.ok, true);
+  assert.equal(firstRelease.reservations.length, 1);
+  assert.equal(state.stockBySku.A, 8);
+  assert.equal(state.stockBySku.B, 2);
+  assert.equal(state.reservations.find((reservation) => reservation.reservationId === "R-1").status, "expired");
+  assert.equal(state.reservations.find((reservation) => reservation.reservationId === "R-2").status, "confirmed");
+  assert.equal(state.events.at(-1).type, "reservation-expired");
+  assert.deepEqual(reservationOverview(state), {
+    activeCount: 0,
+    expiredCount: 1,
+    reservedUnits: 0,
+    nextExpiry: null
+  });
+
+  const eventCount = state.events.length;
+  const secondRelease = releaseExpired(state, { now: new Date("2026-08-09T13:00:00Z") });
+
+  assert.equal(secondRelease.ok, true);
+  assert.equal(secondRelease.reservations.length, 0);
+  assert.equal(state.events.length, eventCount);
+  assert.equal(state.stockBySku.A, 8);
+  assert.equal(state.stockBySku.B, 2);
+});
+
+test("allocation still works with reservation state present", () => {
+  const state = createWarehouseState({ A: 5 });
+  state.reservations.push({
+    reservationId: "R-1",
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 1 }],
+    ttlMinutes: 10,
+    status: "active",
+    createdAt: new Date("2026-08-09T12:00:00Z"),
+    expiresAt: new Date("2026-08-09T12:10:00Z")
+  });
+
+  const result = allocateOrder(state, {
+    orderId: "O-2",
+    lines: [{ skuId: "A", quantity: 2 }]
+  });
+
+  assert.equal(result.ok, true);
+  assert.equal(state.stockBySku.A, 3);
+  assert.equal(state.orders[0].status, "allocated");
+  assert.equal(state.events.at(-1).type, "order-allocated");
+});

