+  );
+
+  assert.throws(
+    () =>
+      reserveStock(state, {
+        reservationId: "R-1",
+        orderId: "",
+        lines: [{ skuId: "A", quantity: 1 }],
+        ttlMinutes: 15,
+        now: new Date("2026-08-09T12:00:00Z")
+      }),
+    /orderId is required/
+  );
+
+  assert.throws(
+    () =>
+      reserveStock(state, {
+        reservationId: "R-1",
+        orderId: "O-1",
+        lines: [{ skuId: "A", quantity: 1 }],
+        ttlMinutes: 0,
+        now: new Date("2026-08-09T12:00:00Z")
