+
+  assert.throws(
+    () =>
+      reserveStock(state, {
+        reservationId: "R-1",
+        orderId: "O-1",
+        lines: [{ skuId: "A", quantity: 0 }],
+        ttlMinutes: 15,
+        now: new Date("2026-08-09T12:00:00Z")
