+++ b/test/infrastructure-reservation.test.mjs
@@ -0,0 +1,143 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import {
+  confirmReservation,
+  createWarehouseState,
+  listReservations,
+  releaseExpired,
+  reserveStock
+} from "../src/domain/warehouse.mjs";
+import { InMemoryWarehouseRepository } from "../src/infrastructure/in-memory-repository.mjs";
+
+function reservationOverview(snapshot) {
+  const activeReservations = snapshot.reservations.filter((reservation) => reservation.status === "active");
+  const expiredReservations = snapshot.reservations.filter((reservation) => reservation.status === "expired");
+
+  return {
+    activeCount: activeReservations.length,
+    expiredCount: expiredReservations.length,
+    reservedUnits: activeReservations.reduce((total, reservation) => {
+      return total + reservation.lines.reduce((lineTotal, line) => lineTotal + line.quantity, 0);
+    }, 0),
+    nextExpiry:
+      activeReservations.length === 0
+        ? null
+        : activeReservations
+            .map((reservation) => reservation.expiresAt)
+            .reduce((earliest, expiresAt) => (expiresAt < earliest ? expiresAt : earliest))
+  };
+}
+
+test("normalizes reservation collections while preserving existing state", () => {
+  const repository = new InMemoryWarehouseRepository({
+    stockBySku: { A: 5 },
+    orders: [{ orderId: "O-1", lines: [{ skuId: "A", quantity: 1 }], status: "allocated" }]
+  });
+
+  const snapshot = repository.load();
+
+  assert.deepEqual(snapshot.stockBySku, { A: 5 });
+  assert.deepEqual(snapshot.orders, [{ orderId: "O-1", lines: [{ skuId: "A", quantity: 1 }], status: "allocated" }]);
+  assert.deepEqual(snapshot.reservations, []);
+  assert.deepEqual(snapshot.events, []);
+
+  snapshot.reservations.push({ reservationId: "R-1" });
+  snapshot.events.push({ type: "reservation-created" });
+
+  assert.deepEqual(repository.load().reservations, []);
+  assert.deepEqual(repository.load().events, []);
+});
+
+test("persists reservation lifecycle state and audit events across load/save", () => {
+  const repository = new InMemoryWarehouseRepository(createWarehouseState({ A: 8, B: 4 }));
+  const now = new Date("2026-08-09T12:00:00Z");
+
+  const initialState = repository.load();
+  const firstReservation = reserveStock(initialState, {
+    reservationId: "R-1",
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 3 }],
+    ttlMinutes: 15,
+    now
+  });
+
+  assert.equal(firstReservation.ok, true);
+  repository.save(initialState);
+
+  const afterFirstSave = repository.load();
+  assert.equal(afterFirstSave.stockBySku.A, 5);
+  assert.equal(afterFirstSave.reservations.length, 1);
+  assert.equal(afterFirstSave.reservations[0].status, "active");
+  assert.deepEqual(afterFirstSave.reservations[0].expiresAt, new Date("2026-08-09T12:15:00Z"));
+  assert.deepEqual(afterFirstSave.events.map((event) => event.type), ["reservation-created"]);
+  assert.deepEqual(reservationOverview(afterFirstSave), {
+    activeCount: 1,
+    expiredCount: 0,
+    reservedUnits: 3,
+    nextExpiry: new Date("2026-08-09T12:15:00Z")
+  });
+
+  afterFirstSave.reservations[0].status = "tampered";
+  assert.equal(repository.load().reservations[0].status, "active");
+
+  const secondState = repository.load();
+  const secondReservation = reserveStock(secondState, {
+    reservationId: "R-2",
+    orderId: "O-2",
+    lines: [{ skuId: "B", quantity: 2 }],
+    ttlMinutes: 60,
+    now
+  });
+
+  assert.equal(secondReservation.ok, true);
+  const confirmation = confirmReservation(secondState, { reservationId: "R-2" });
+
+  assert.equal(confirmation.ok, true);
+  assert.equal(secondState.stockBySku.B, 2);
+  assert.equal(secondState.orders.length, 1);
+  assert.equal(secondState.orders[0].status, "confirmed");
+  assert.deepEqual(secondState.events.map((event) => event.type), [
+    "reservation-created",
+    "reservation-created",
+    "reservation-confirmed"
+  ]);
+
+  repository.save(secondState);
+
+  const beforeRelease = repository.load();
+  const released = releaseExpired(beforeRelease, { now: new Date("2026-08-09T12:30:00Z") });
+
+  assert.equal(released.ok, true);
+  assert.equal(released.reservations.length, 1);
+  assert.equal(beforeRelease.stockBySku.A, 8);
+  assert.equal(beforeRelease.stockBySku.B, 2);
+  assert.deepEqual(listReservations(beforeRelease).map((reservation) => reservation.status), [
+    "expired",
+    "confirmed"
+  ]);
+  assert.deepEqual(beforeRelease.events.map((event) => event.type), [
+    "reservation-created",
+    "reservation-created",
+    "reservation-confirmed",
+    "reservation-expired"
+  ]);
+  assert.deepEqual(reservationOverview(beforeRelease), {
+    activeCount: 0,
+    expiredCount: 1,
+    reservedUnits: 0,
+    nextExpiry: null
+  });
+
+  repository.save(beforeRelease);
+
+  const afterRelease = repository.load();
+  assert.equal(afterRelease.stockBySku.A, 8);
+  assert.equal(afterRelease.stockBySku.B, 2);
+  assert.deepEqual(afterRelease.reservations.map((reservation) => reservation.status), ["expired", "confirmed"]);
+  assert.deepEqual(afterRelease.events.map((event) => event.type), [
+    "reservation-created",
+    "reservation-created",
+    "reservation-confirmed",
+    "reservation-expired"
+  ]);
+});

