+import test from "node:test";
+import assert from "node:assert/strict";
+import { createWarehouseState } from "../src/domain/warehouse.mjs";
+import { InMemoryWarehouseRepository } from "../src/infrastructure/in-memory-repository.mjs";
+import { WarehouseService } from "../src/application/warehouse-service.mjs";
+
+function reservationOverview(snapshot) {
+  const activeReservations = snapshot.reservations.filter((reservation) => reservation.status === "active");
+  const expiredReservations = snapshot.reservations.filter((reservation) => reservation.status === "expired");
+
+  return {
+    activeCount: activeReservations.length,
+    expiredCount: expiredReservations.length,
+    reservedUnits: activeReservations.reduce((total, reservation) => {
+      return total + reservation.lines.reduce((lineTotal, line) => lineTotal + line.quantity, 0);
+    }, 0),
+    nextExpiry:
+      activeReservations.length === 0
+        ? null
+        : activeReservations
+            .map((reservation) => reservation.expiresAt)
+            .reduce((earliest, expiresAt) => (expiresAt < earliest ? expiresAt : earliest))
+  };
+}
+
+function buildService(initialStock = { A: 8, B: 4 }) {
+  const repository = new InMemoryWarehouseRepository(createWarehouseState(initialStock));
+  const service = new WarehouseService(repository);
+  return { repository, service };
+}
+
+test("wires the reservation lifecycle through the application service", () => {
+  const { repository, service } = buildService({ A: 10, B: 5 });
+  const now = new Date("2026-08-09T12:00:00Z");
+
+  const firstReservation = service.reserveStock({
+    reservationId: "R-1",
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 3 }],
+    ttlMinutes: 30,
+    now
+  });
+  const secondReservation = service.reserveStock({
+    reservationId: "R-2",
+    orderId: "O-2",
+    lines: [{ skuId: "B", quantity: 2 }],
+    ttlMinutes: 15,
+    now
+  });
+
+  assert.equal(firstReservation.ok, true);
+  assert.deepEqual(firstReservation.reservation, {
+    reservationId: "R-1",
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 3 }],
+    ttlMinutes: 30,
+    status: "active",
+    createdAt: new Date("2026-08-09T12:00:00.000Z"),
+    expiresAt: new Date("2026-08-09T12:30:00.000Z")
+  });
+  assert.equal(secondReservation.ok, true);
+  assert.deepEqual(secondReservation.reservation.expiresAt, new Date("2026-08-09T12:15:00.000Z"));
+
+  assert.equal(repository.load().stockBySku.A, 7);
+  assert.equal(repository.load().stockBySku.B, 3);
+  assert.deepEqual(service.listReservations().map((entry) => entry.status), ["active", "active"]);
+  assert.deepEqual(reservationOverview(service.snapshot()), {
+    activeCount: 2,
+    expiredCount: 0,
+    reservedUnits: 5,
+    nextExpiry: new Date("2026-08-09T12:15:00.000Z")
+  });
+  assert.deepEqual(repository.load().events.map((event) => event.type), ["reservation-created", "reservation-created"]);
+
+  const confirmation = service.confirmReservation({ reservationId: "R-1" });
+
+  assert.equal(confirmation.ok, true);
+  assert.equal(confirmation.order.orderId, "O-1");
+  assert.equal(confirmation.order.reservationId, "R-1");
+  assert.equal(repository.load().stockBySku.A, 7);
+  assert.equal(repository.load().stockBySku.B, 3);
+  assert.deepEqual(service.listReservations().map((entry) => entry.status), ["confirmed", "active"]);
+  assert.deepEqual(repository.load().events.map((event) => event.type), [
+    "reservation-created",
+    "reservation-created",
+    "reservation-confirmed"
+  ]);
+
+  const released = service.releaseExpired({ now: new Date("2026-08-09T12:20:00Z") });
+
+  assert.equal(released.ok, true);
+  assert.equal(released.reservations.length, 1);
+  assert.equal(released.reservations[0].reservationId, "R-2");
+  assert.equal(released.reservations[0].status, "expired");
+  assert.equal(repository.load().stockBySku.A, 7);
+  assert.equal(repository.load().stockBySku.B, 5);
+  assert.deepEqual(service.listReservations().map((entry) => entry.status), ["confirmed", "expired"]);
+  assert.deepEqual(repository.load().events.map((event) => event.type), [
+    "reservation-created",
+    "reservation-created",
+    "reservation-confirmed",
+    "reservation-expired"
+  ]);
+  assert.deepEqual(reservationOverview(service.snapshot()), {
+    activeCount: 0,
+    expiredCount: 1,
+    reservedUnits: 0,
+    nextExpiry: null
+  });
+
+  const secondRelease = service.releaseExpired({ now: new Date("2026-08-09T13:00:00Z") });
+
+  assert.equal(secondRelease.ok, true);
+  assert.equal(secondRelease.reservations.length, 0);
+  assert.equal(repository.load().stockBySku.A, 7);
+  assert.equal(repository.load().stockBySku.B, 5);
+  assert.deepEqual(repository.load().events.map((event) => event.type), [
+    "reservation-created",
+    "reservation-created",
+    "reservation-confirmed",
+    "reservation-expired"
+  ]);
+});
+
+test("validates duplicate reservation and order identifiers and leaves stock unchanged on failure", () => {
+  const { repository, service } = buildService({ A: 5 });
+  const now = new Date("2026-08-09T12:00:00Z");
+
+  const first = service.reserveStock({
+    reservationId: "R-1",
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 2 }],
+    ttlMinutes: 15,
+    now
+  });
+
+  assert.equal(first.ok, true);
+  assert.equal(repository.load().stockBySku.A, 3);
+
+  assert.throws(
+    () =>
+      service.reserveStock({
+        reservationId: "R-1",
+        orderId: "O-2",
+        lines: [{ skuId: "A", quantity: 1 }],
+        ttlMinutes: 15,
+        now
+      }),
+    /reservationId already exists/
+  );
+
+  assert.throws(
+    () =>
+      service.reserveStock({
+        reservationId: "R-2",
+        orderId: "O-1",
+        lines: [{ skuId: "A", quantity: 1 }],
+        ttlMinutes: 15,
+        now
+      }),
+    /orderId already exists/
+  );
+
+  const shortage = service.reserveStock({
+    reservationId: "R-3",
+    orderId: "O-3",
+    lines: [{ skuId: "A", quantity: 4 }],
+    ttlMinutes: 15,
+    now
+  });
+
+  assert.equal(shortage.ok, false);
+  assert.deepEqual(shortage.shortages, [{ skuId: "A", quantity: 4, missing: 1 }]);
+
+  assert.equal(repository.load().stockBySku.A, 3);
+  assert.deepEqual(repository.load().events.map((event) => event.type), ["reservation-created"]);
+});
+
+test("preserves allocation and restock behavior", () => {
+  const { repository, service } = buildService({ A: 8, B: 3 });
+
+  const allocated = service.allocateOrder({
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 2 }]
+  });
+
+  assert.equal(allocated.ok, true);
+  assert.equal(repository.load().stockBySku.A, 6);
+  assert.deepEqual(repository.load().orders, [
+    { orderId: "O-1", lines: [{ skuId: "A", quantity: 2 }], status: "allocated" }
+  ]);
+  assert.equal(repository.load().events.at(-1).type, "order-allocated");
+
+  assert.equal(service.restock({ skuId: "B", quantity: 4 }), 7);
+  assert.equal(repository.load().stockBySku.B, 7);
+  assert.equal(repository.load().events.at(-1).type, "stock-restocked");
+});

