+    reservationId: "R-1",
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 3 }],
+    ttlMinutes: 30,
+    status: "active",
+    createdAt: new Date("2026-08-09T12:00:00.000Z"),
+    expiresAt: new Date("2026-08-09T12:30:00.000Z")
+  });
+  assert.equal(secondReservation.ok, true);
+  assert.deepEqual(secondReservation.reservation.expiresAt, new Date("2026-08-09T12:15:00.000Z"));
+
+  assert.equal(repository.load().stockBySku.A, 7);
+  assert.equal(repository.load().stockBySku.B, 3);
+  assert.deepEqual(service.listReservations().map((entry) => entry.status), ["active", "active"]);
