+test("preserves allocation and restock behavior", () => {
+  const { repository, service } = buildService({ A: 8, B: 3 });
+
+  const allocated = service.allocateOrder({
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 2 }]
