+import test from "node:test";
+import assert from "node:assert/strict";
+import { buildDashboardModel } from "../src/ui/dashboard-view.mjs";
+
+test("exposes reservation metrics without changing the existing dashboard sections", () => {
+  const snapshot = {
+    stockBySku: { A: 5, B: 2 },
+    orders: [
+      { orderId: "O-1", lines: [{ skuId: "A", quantity: 1 }], status: "allocated" },
+      { orderId: "O-2", reservationId: "R-2", lines: [{ skuId: "B", quantity: 1 }], status: "confirmed" }
+    ],
+    reservations: [
+      {
+        reservationId: "R-1",
+        orderId: "O-1",
+        lines: [{ skuId: "A", quantity: 2 }],
+        ttlMinutes: 30,
+        status: "active",
+        createdAt: new Date("2026-08-09T12:00:00Z"),
+        expiresAt: new Date("2026-08-09T12:30:00Z")
+      },
+      {
+        reservationId: "R-2",
+        orderId: "O-2",
+        lines: [{ skuId: "B", quantity: 1 }],
+        ttlMinutes: 10,
+        status: "expired",
+        createdAt: new Date("2026-08-09T11:30:00Z"),
+        expiresAt: new Date("2026-08-09T11:40:00Z"),
+        expiredAt: new Date("2026-08-09T11:40:00Z")
+      }
+    ],
+    events: [
+      { type: "reservation-created", reservationId: "R-1" },
+      { type: "reservation-expired", reservationId: "R-2" },
+      { type: "order-allocated", orderId: "O-1" }
+    ]
+  };
+
+  const model = buildDashboardModel(snapshot);
+
+  assert.deepEqual(model, {
+    skuCount: 2,
+    availableUnits: 7,
+    allocatedOrders: 1,
+    recentEvents: [
+      { type: "order-allocated", orderId: "O-1" },
+      { type: "reservation-expired", reservationId: "R-2" },
+      { type: "reservation-created", reservationId: "R-1" }
+    ]
+  });
+  assert.deepEqual(Object.keys(model), ["skuCount", "availableUnits", "allocatedOrders", "recentEvents"]);
+  assert.deepEqual(model.reservations, {
+    activeCount: 1,
+    expiredCount: 1,
+    reservedUnits: 2,
+    nextExpiry: new Date("2026-08-09T12:30:00Z")
+  });
+});

