+import test from "node:test";
+import assert from "node:assert/strict";
+import { createWarehouseState } from "../src/domain/warehouse.mjs";
+import { InMemoryWarehouseRepository } from "../src/infrastructure/in-memory-repository.mjs";
+import { WarehouseService } from "../src/application/warehouse-service.mjs";
+import { createWarehouseApi } from "../src/api/warehouse-api.mjs";
+import { buildDashboardModel } from "../src/ui/dashboard-view.mjs";
+
+function reservationOverview(snapshot) {
+  const reservations = Array.isArray(snapshot.reservations) ? snapshot.reservations : [];
+  const activeReservations = reservations.filter((reservation) => reservation.status === "active");
+  const expiredReservations = reservations.filter((reservation) => reservation.status === "expired");
+
+  return {
+    activeCount: activeReservations.length,
+    expiredCount: expiredReservations.length,
+    reservedUnits: activeReservations.reduce((total, reservation) => {
+      return total + reservation.lines.reduce((lineTotal, line) => lineTotal + line.quantity, 0);
+    }, 0),
+    nextExpiry:
+      activeReservations.length === 0
+        ? null
+        : activeReservations
+            .map((reservation) => reservation.expiresAt)
+            .reduce((earliest, expiresAt) => (expiresAt < earliest ? expiresAt : earliest))
+  };
+}
+
+function fixture(initialStock = { A: 10, B: 5 }) {
+  const repository = new InMemoryWarehouseRepository(createWarehouseState(initialStock));
+  const service = new WarehouseService(repository);
+  const api = createWarehouseApi(service);
+  return { repository, service, api };
+}
+
+test("proves the reservation lifecycle end to end while preserving allocation and restock behavior", () => {
+  const { repository, api } = fixture();
+  const now = new Date("2026-08-09T12:00:00Z");
+
+  assert.equal(typeof api.allocateOrder, "function");
+  assert.equal(typeof api.restock, "function");
+  assert.equal(typeof api.reserveStock, "function");
+  assert.equal(typeof api.confirmReservation, "function");
+  assert.equal(typeof api.releaseExpired, "function");
+  assert.equal(typeof api.listReservations, "function");
+  assert.equal(typeof api.getSnapshot, "function");
+
+  const reservation = api.reserveStock({
+    reservationId: "R-1",
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 3 }],
+    ttlMinutes: 30,
+    now
+  });
+
+  assert.equal(reservation.ok, true);
+  assert.deepEqual(reservation.reservation, {
+    reservationId: "R-1",
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 3 }],
+    ttlMinutes: 30,
+    status: "active",
+    createdAt: new Date("2026-08-09T12:00:00.000Z"),
+    expiresAt: new Date("2026-08-09T12:30:00.000Z")
+  });
+  assert.equal(api.getSnapshot().stockBySku.A, 7);
+  assert.deepEqual(repository.load().events, [
+    {
+      type: "reservation-created",
+      reservationId: "R-1",
+      orderId: "O-1",
+      expiresAt: new Date("2026-08-09T12:30:00.000Z")
+    }
+  ]);
+  assert.deepEqual(api.listReservations(), [reservation.reservation]);
+  assert.deepEqual(buildDashboardModel(api.getSnapshot()), {
+    skuCount: 2,
+    availableUnits: 12,
+    allocatedOrders: 0,
+    recentEvents: [{ type: "reservation-created", reservationId: "R-1", orderId: "O-1", expiresAt: new Date("2026-08-09T12:30:00.000Z") }]
+  });
+  assert.deepEqual(buildDashboardModel(api.getSnapshot()).reservations, {
+    activeCount: 1,
+    expiredCount: 0,
+    reservedUnits: 3,
+    nextExpiry: new Date("2026-08-09T12:30:00.000Z")
+  });
+  assert.deepEqual(reservationOverview(api.getSnapshot()), {
+    activeCount: 1,
+    expiredCount: 0,
+    reservedUnits: 3,
+    nextExpiry: new Date("2026-08-09T12:30:00.000Z")
+  });
+
+  const confirmation = api.confirmReservation({ reservationId: "R-1" });
+
+  assert.equal(confirmation.ok, true);
+  assert.deepEqual(confirmation.order, {
+    orderId: "O-1",
+    reservationId: "R-1",
+    lines: [{ skuId: "A", quantity: 3 }],
+    status: "confirmed"
+  });
+  assert.equal(api.getSnapshot().stockBySku.A, 7);
+  assert.deepEqual(api.listReservations().map((entry) => entry.status), ["confirmed"]);
+  assert.deepEqual(api.getSnapshot().events.map((event) => event.type), [
+    "reservation-created",
+    "reservation-confirmed"
+  ]);
+
+  const secondReservation = api.reserveStock({
+    reservationId: "R-2",
+    orderId: "O-2",
+    lines: [{ skuId: "B", quantity: 2 }],
+    ttlMinutes: 15,
+    now
+  });
+
+  assert.equal(secondReservation.ok, true);
+  assert.equal(api.getSnapshot().stockBySku.B, 3);
+  assert.deepEqual(buildDashboardModel(api.getSnapshot()).reservations, {
+    activeCount: 1,
+    expiredCount: 0,
+    reservedUnits: 2,
+    nextExpiry: new Date("2026-08-09T12:15:00.000Z")
+  });
+
+  const release = api.releaseExpired({ now: new Date("2026-08-09T12:20:00Z") });
+
+  assert.equal(release.ok, true);
+  assert.equal(release.reservations.length, 1);
+  assert.equal(release.reservations[0].reservationId, "R-2");
+  assert.equal(release.reservations[0].status, "expired");
+  assert.equal(api.getSnapshot().stockBySku.B, 5);
+  assert.deepEqual(api.listReservations().map((entry) => entry.status), ["confirmed", "expired"]);
+  assert.deepEqual(api.getSnapshot().events.map((event) => event.type), [
+    "reservation-created",
+    "reservation-confirmed",
+    "reservation-created",
+    "reservation-expired"
+  ]);
+  assert.deepEqual(buildDashboardModel(api.getSnapshot()).reservations, {
+    activeCount: 0,
+    expiredCount: 1,
+    reservedUnits: 0,
+    nextExpiry: null
+  });
+
+  const secondRelease = api.releaseExpired({ now: new Date("2026-08-09T13:00:00Z") });
+
+  assert.equal(secondRelease.ok, true);
+  assert.equal(secondRelease.reservations.length, 0);
+  assert.deepEqual(api.getSnapshot().events.map((event) => event.type), [
+    "reservation-created",
+    "reservation-confirmed",
+    "reservation-created",
+    "reservation-expired"
+  ]);
+
+  const allocated = api.allocateOrder({
+    orderId: "O-3",
+    lines: [{ skuId: "A", quantity: 2 }]
+  });
+
+  assert.equal(allocated.ok, true);
+  assert.equal(api.getSnapshot().stockBySku.A, 5);
+  assert.equal(api.restock({ skuId: "B", quantity: 4 }).quantity, 9);
+});
+
+test("keeps reservation validation and repository persistence intact", () => {
+  const { repository, service } = fixture({ A: 5 });
+  const now = new Date("2026-08-09T12:00:00Z");
+
+  assert.throws(
+    () =>
+      service.reserveStock({
+        reservationId: "",
+        orderId: "O-1",
+        lines: [{ skuId: "A", quantity: 1 }],
+        ttlMinutes: 15,
+        now
+      }),
+    /reservationId is required/
+  );
+
+  assert.throws(
+    () =>
+      service.reserveStock({
+        reservationId: "R-1",
+        orderId: "",
+        lines: [{ skuId: "A", quantity: 1 }],
+        ttlMinutes: 15,
+        now
+      }),
+    /orderId is required/
+  );
+
+  assert.throws(
+    () =>
+      service.reserveStock({
+        reservationId: "R-1",
+        orderId: "O-1",
+        lines: [{ skuId: "A", quantity: 1 }],
+        ttlMinutes: 0,
+        now
+      }),
+    /ttlMinutes must be a positive integer/
+  );
+
+  assert.throws(
+    () =>
+      service.reserveStock({
+        reservationId: "R-1",
+        orderId: "O-1",
+        lines: [{ skuId: "A", quantity: 0 }],
+        ttlMinutes: 15,
+        now
+      }),
+    /quantity must be a positive integer/
+  );
+
+  const first = service.reserveStock({
+    reservationId: "R-1",
+    orderId: "O-1",
+    lines: [{ skuId: "A", quantity: 2 }],
+    ttlMinutes: 15,
+    now
+  });
+
+  assert.equal(first.ok, true);
+  assert.equal(repository.load().stockBySku.A, 3);
+
+  assert.throws(
+    () =>
+      service.reserveStock({
+        reservationId: "R-1",
+        orderId: "O-2",
+        lines: [{ skuId: "A", quantity: 1 }],
+        ttlMinutes: 15,
+        now
+      }),
+    /reservationId already exists/
+  );
+
+  assert.throws(
+    () =>
+      service.reserveStock({
+        reservationId: "R-2",
+        orderId: "O-1",
+        lines: [{ skuId: "A", quantity: 1 }],
+        ttlMinutes: 15,
+        now
+      }),
+    /orderId already exists/
+  );
+
+  const shortage = service.reserveStock({
+    reservationId: "R-3",
+    orderId: "O-3",
+    lines: [{ skuId: "A", quantity: 4 }],
+    ttlMinutes: 15,
+    now
+  });
+
+  assert.equal(shortage.ok, false);
+  assert.deepEqual(shortage.shortages, [{ skuId: "A", quantity: 4, missing: 1 }]);
+  assert.equal(repository.load().stockBySku.A, 3);
+  assert.deepEqual(repository.load().events.map((event) => event.type), ["reservation-created"]);
+
+  const beforeSave = repository.load();
+  repository.save(beforeSave);
+  const afterSave = repository.load();
+  assert.deepEqual(afterSave.reservations, beforeSave.reservations);
+  assert.deepEqual(afterSave.events, beforeSave.events);
+});

